const params=new URLSearchParams(location.search),form=params.get('form')==='services'?'services':'life';
const source=CSLBook[form],$=id=>document.getElementById(id),esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let activity=params.has('activity')?Number(params.get('activity')):-1;if(!Number.isInteger(activity)||activity< -1||activity>=source.length)activity=-1;
let view='overview',step=0,timer=null,lastEvidence='',inMemory={},reviewPage=null;
const isIcon=src=>(CSLBook.icons||[]).includes(src);
const key='skillos.csl6.workbook.'+form+'.v1';try{inMemory=JSON.parse(localStorage.getItem(key)||'{}')}catch{}
const title=form==='life'?'Terrace & Container Gardening':'Farm to Table — School Health & Wellness Kiosk';
$('title').textContent=title;$('boundary').textContent='Original Class 6 workbook · No outside pictures or sample outcomes.';
function state(){return inMemory[activity]||(inMemory[activity]={fields:{},reflection:'',step:0})}
function persist(){try{localStorage.setItem(key,JSON.stringify(inMemory));return true}catch{return false}}
function stop(){clearInterval(timer);timer=null;window.speechSynthesis?.cancel()}
function feedback(t){const el=$('feedback');if(el)el.textContent=t;lastEvidence=t}
function image(src,alt='Original workbook illustration'){return '<img class="original-figure '+(isIcon(src)?'source-icon':'')+'" src="'+src+'" alt="'+esc(alt)+'">'}
function paragraph(b){const t=b.text||'';return (b.images||[]).map(i=>image(i)).join('')+(t?'<p>'+esc(t)+'</p>':'')}
function blocks(items){return items.map(b=>b.kind==='table'?'<div class="table-scroll"><table>'+b.rows.map((r,i)=>'<tr>'+r.map(c=>'<'+(i?'td':'th')+'>'+c.images.map(x=>image(x)).join('')+esc(c.text)+'</'+(i?'td':'th')+'>').join('')+'</tr>').join('')+'</table></div>':paragraph(b)).join('')}
const field=(id,label,type='text',value='')=>'<label>'+esc(label)+'<input id="'+id+'" data-field="'+id+'" type="'+type+'" value="'+esc(state().fields[id]??value)+'" '+(type==='number'?'min="0"':'')+'></label>';
const notes=(id,label)=>'<label>'+esc(label)+'<textarea data-field="'+id+'">'+esc(state().fields[id]||'')+'</textarea></label>';
function bindFields(){document.querySelectorAll('[data-field]').forEach(e=>{if(e.type==='checkbox')e.checked=Boolean(state().fields[e.dataset.field]);e.oninput=()=>{state().fields[e.dataset.field]=e.type==='checkbox'?e.checked:e.value;persist()}})}
function checkbox(id,label){return '<label class="check"><input type="checkbox" data-field="'+id+'">'+esc(label)+'</label>'}
function current(){return source[activity]}
function openPage(n){const allowed=activity<0?(form==='life'?[9,10,11,12,13,14,15]:[40,41,42,43,44,45,46,47]):current().sourcePages;$('dialog-page').innerHTML=allowed.map(p=>'<option '+(p===n?'selected':'')+'>'+p+'</option>').join('');$('page-image').src='book/page-'+n+'.webp';$('page-image').alt='Original Class 6 workbook page '+n;$('page-dialog').showModal()}
$('dialog-page').onchange=()=>{$('page-image').src='book/page-'+$('dialog-page').value+'.webp';$('page-image').alt='Original Class 6 workbook page '+$('dialog-page').value};$('close-page').onclick=()=>{$('page-dialog').close();if(document.fullscreenElement)document.exitFullscreen?.()};$('fullscreen').onclick=()=>{$('page-dialog').requestFullscreen?.().catch(()=>{})};
function render(){stop();lastEvidence='';$('activities').innerHTML=['Meet the Lab',...source.map(a=>a.title.replace(/^ACTIVITY\s+\d+\s*[•·]?\s*/i,''))].map((t,i)=>'<button data-activity="'+(i-1)+'" aria-current="'+(activity===i-1)+'">'+(i?i+' · ':'')+esc(t)+'</button>').join('');document.querySelectorAll('[data-activity]').forEach(b=>b.onclick=()=>{activity=Number(b.dataset.activity);step=state().step||0;view='overview';history.replaceState(null,'','?form='+form+'&activity='+activity);render()});$('activity-title').textContent=activity<0?'Meet the Lab':current().title;$('page').textContent=activity<0?'WORKBOOK TOOLKIT':('ORIGINAL WORKBOOK · PAGES '+current().sourcePages[0]+'–'+current().sourcePages.at(-1));$('mission').textContent=activity<0?'Know your materials before you begin.':(current().overview[2]?.text||'');$('reflection').value=state().reflection||'';$('save-status').textContent='';$('view-tabs').innerHTML=activity<0?'':['overview','steps','records','pages'].map(v=>'<button data-view="'+v+'" aria-current="'+(view===v)+'">'+({overview:'Project overview',steps:'Follow picture steps',records:'My records',pages:'Original pages'}[v])+'</button>').join('');document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render()});if(activity<0)meet();else if(view==='overview')overview();else if(view==='steps')stepView();else if(view==='records')records();else pagesView();bindFields();document.querySelectorAll('[data-open-page]').forEach(b=>b.onclick=()=>openPage(+b.dataset.openPage))}
function overview(){$('workspace').innerHTML='<section class="card source-overview">'+blocks(current().overview.slice(3))+'<button id="begin">Follow the workbook’s picture steps →</button></section>';$('begin').onclick=()=>{view='steps';step=0;state().step=0;render()}}
function meet(){const list=CSLBook.toolkit[form];$('workspace').innerHTML='<div class="meet-grid"><section class="card"><h2>'+(form==='life'?'MEET YOUR GARDEN TOOLKIT':'MEET THE FARM TO TABLE TOOLKIT')+'</h2>'+(form==='services'?image('book/services-toolkit.webp','Original Farm to Table toolkit illustration · page 45'):'')+'<div class="parts">'+list.map((t,i)=>'<button data-tool="'+i+'" aria-pressed="false">'+(t.image?image(t.image,t.name):'')+'<strong>'+esc(t.name)+'</strong></button>').join('')+'</div></section><section class="card selected-tool"><div id="tool-picture"></div><h2 id="tool-name">Select an item</h2><p id="tool-usage">Its original workbook description will appear here.</p><p id="tool-when"></p><button id="listen" disabled>Listen in English</button> <button id="stop-audio" class="secondary">Stop</button><p id="audio-status" role="status"></p><button data-open-page="'+(form==='life'?12:45)+'" class="secondary">See original toolkit page</button></section></div>';let selected;document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>{stop();selected=list[+b.dataset.tool];document.querySelectorAll('[data-tool]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$('tool-name').textContent=selected.name;$('tool-usage').textContent=selected.usage;$('tool-when').textContent=selected.when;$('tool-picture').innerHTML=selected.image?image(selected.image,selected.name):'';$('listen').disabled=!window.speechSynthesis||!window.SpeechSynthesisUtterance});$('listen').onclick=()=>{stop();const spoken=new SpeechSynthesisUtterance(selected.name+'. '+selected.usage+'. '+selected.when);spoken.lang='en-IN';spoken.onerror=()=>{$('audio-status').textContent='Audio is unavailable. Read the workbook description above.'};window.speechSynthesis.speak(spoken)};$('stop-audio').onclick=stop}
function stepView(){const a=current();step=Math.min(step,a.steps.length-1);if(step<0){$('workspace').innerHTML='<section class="card">'+blocks(a.pages[1]||a.overview)+'</section>';return}const s=a.steps[step];let figure=s.blocks.flatMap(b=>b.images||[]).find(img=>!isIcon(img))||a.stageFigure||s.pageFigure;const body=s.blocks.map(b=>b.kind==='paragraph'?{...b,images:[]}:b).filter(b=>b.text||b.kind==='table');$('workspace').innerHTML='<div class="step-layout"><aside class="card step-list"><h3>Workbook sequence</h3>'+a.steps.map((t,i)=>'<button data-step="'+i+'" aria-current="'+(i===step)+'">'+'<small>Page '+t.page+'</small>'+esc(t.title)+'</button>').join('')+'</aside><div><section class="card source-stage"><div class="source-bar"><span>WORKBOOK STEP · PAGE '+s.page+'</span><button class="secondary" data-open-page="'+s.page+'">Enlarge original page</button></div><h2>'+esc(s.title)+'</h2>'+(figure?'<p class="fine">Original activity artwork · page '+(figure===a.stageFigure?a.sourcePages[0]:s.page)+'</p><div class="picture-stage" id="picture-stage">'+image(figure,s.title)+'<div id="motion-layer"></div></div>':'')+'<div class="source-instructions">'+blocks(body)+'</div><div class="step-actions"><button id="previous" class="secondary" '+(step===0?'disabled':'')+'>← Previous step</button><span>Step '+(step+1)+' of '+a.steps.length+'</span><button id="next" '+(step===a.steps.length-1?'disabled':'')+'>Next step →</button></div></section><section class="card interaction"><span class="eyebrow">INTERACTIVE WORKBOOK DESK</span><div id="desk"></div><div id="feedback" class="feedback" role="status">Use the workbook step and record what you actually observe.</div></section></div></div>';document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{step=+b.dataset.step;state().step=step;persist();render()});$('previous').onclick=()=>{step--;state().step=step;persist();render()};$('next').onclick=()=>{step++;state().step=step;persist();render()};if(form==='life')gardenDesk();else kioskDesk()}
function records(){const a=current();$('workspace').innerHTML='<section class="card"><h2>Record your own work</h2><p>The prompts and tables below are copied from this activity’s workbook pages. Source examples remain labelled MODEL ONLY. Staff confirmation remains a real-world staff task.</p>'+a.pages.map((pg,pi)=>'<details class="record-page" '+(pi===a.pages.findIndex(page=>/LOGBOOK|RECORD|OUR.*LOG|PROPOSAL/.test(page[1]?.text||''))?'open':'')+'><summary>Page '+a.sourcePages[pi]+' · '+esc(pg[1]?.text||'')+'</summary>'+editable(pg.slice(2),'p'+a.sourcePages[pi])+'</details>').join('')+'</section>'}
function editable(items,prefix){return items.map((b,i)=>{if(b.kind==='table')return '<div class="table-scroll"><table>'+b.rows.map((row,ri)=>'<tr>'+row.map((c,ci)=>'<'+(ri?'td':'th')+'>'+c.images.map(x=>image(x)).join('')+(c.text.includes('___')?'<label><span>'+esc(c.text.replace(/_{3,}/g,' [record] '))+'</span><textarea aria-label="Page record row '+ri+' column '+ci+'" data-field="'+prefix+'-'+i+'-'+ri+'-'+ci+'">'+esc(state().fields[prefix+'-'+i+'-'+ri+'-'+ci]||'')+'</textarea></label>':esc(c.text))+'</'+(ri?'td':'th')+'>').join('')+'</tr>').join('')+'</table></div>';let t=b.text||'';if(t.includes('___'))return notes(prefix+'-'+i,t.replace(/_{3,}/g,' [record] '));if(t.startsWith('□'))return t.split('□').map((label,j)=>label.trim()?checkbox(prefix+'-'+i+'-'+j,label.trim()):'').join('');return paragraph(b)}).join('')}
function pagesView(){$('workspace').innerHTML='<section class="card"><h2>Original workbook pages</h2><p>These are the original pages rendered from your Class 6 Word workbook, with their artwork and wording unchanged. Select a page to enlarge it.</p><div class="page-thumbs">'+current().sourcePages.map(n=>'<button data-open-page="'+n+'"><img loading="lazy" src="book/page-'+n+'.webp" alt="Original workbook page '+n+'"><span>Page '+n+'</span></button>').join('')+'</div></section>'}
function desk(html){$('desk').innerHTML=html+'<details class="source-task"><summary>Complete this step’s original workbook prompts</summary>'+editable(current().steps[step].blocks,'step-'+step)+'</details>'}
function general(){desk(notes('step-'+step+'-work','My work / original evidence for this step')+notes('step-'+step+'-pending','What needs a teacher check or later observation?'))}
function gardenDesk(){
 if(activity===0&&step===1){desk('<h3>Sunlight observation map</h3>'+notes('sun-directions','Checked directions / north on my sketch')+field('sun-time','Observation date / time')+'<label>Condition observed<select id="sun"><option>Direct sun</option><option>Shade</option><option>Cloud obscures the observation</option></select></label>'+notes('sun-evidence','Spot, current weather and shadows from tanks, towers or trees')+'<button id="sun-check">Check what one visit can tell us</button>');$('sun-check').onclick=()=>feedback('Record agreed observations over time. The book treats sunlight hours as a crop-, season- and locally checked planning question, not one rule for every crop. Never look directly at the sun.')}
 else if(activity===0&&step===4){desk('<h3>Measure the trial footprint</h3>'+field('layout-length','Measured length · cm','number')+field('layout-width','Measured width · cm','number')+'<button id="footprint">Calculate my footprint</button>'+notes('layout-clearance','Teacher-approved paths, drains, boundary clearance and placement'));$('footprint').onclick=()=>{if($('layout-length').value===''||$('layout-width').value===''||+$('layout-length').value<=0||+$('layout-width').value<=0){feedback('Enter measured dimensions first. The book’s approximately 60 × 90 cm rectangle is a trial example, not structural approval.');return}feedback('Measured rectangular footprint: '+(+$('layout-length').value*+$('layout-width').value/10000).toFixed(3)+' m². The teacher approves load, clearance and placement; area alone is not a safety decision.')}}
 else if(activity===1&&step===0){desk('<h3>Hydrate according to this product</h3>'+notes('coir-directions','Product water / soaking instructions checked with teacher')+field('coir-water','Actual measured water used · mL','number')+field('coir-time','Actual softening time · minutes','number')+'<p>No fixed 4 L or 15-minute result is generated. Let excess water drain before measuring.</p>')}
 else if(activity===1&&step===1){desk('<h3>Measure equal loose cups · 5 : 3 : 2</h3>'+field('mix-total','Planned total mix volume · same unit throughout','number')+'<button id="mix">Calculate the workbook proportions</button><div id="mix-result" class="metrics"></div>'+notes('mix-actual','Actual cup size, measured parts and mixing observation'));$('mix').onclick=()=>{const total=+$('mix-total').value;if(!total||total<0){feedback('Enter a positive planned total volume.');return}const m=CSLModel.mix(total);$('mix-result').innerHTML=Object.entries(m).map(([k,v])=>'<div class="metric">'+k+'<b>'+v.toFixed(2)+'</b></div>').join('');feedback('Measure 5 parts prepared cocopeat, 3 parts mature vermicompost and 2 parts perlite using the same loose, level measure. This is a proportion calculation, not a guarantee of drainage or growth.')}}
 else if(activity===1&&step===4){desk(field('drain-water','Actual measured water added · mL','number')+field('drain-time','Time when drainage first seen')+notes('drain-observation','Starting moisture / pooling / tray condition')+'<button id="drain-review">Review the source check</button>');$('drain-review').onclick=()=>feedback('Stop and ask the teacher if water pools or the tray fills. Drainage time varies with the bag, mix and starting moisture; there is no universal 2–3 minute pass mark.')}
 else if(activity===2&&step===0){desk('<h3>Floating and sinking observation</h3>'+field('seed-sample','Original seed sample count','number')+field('float','Seeds floating after two minutes','number')+field('sink','Seeds sinking after two minutes','number')+'<button id="seeds-check">Check counts and next observation</button>'+notes('seed-follow-up','Separate labelled damp-paper groups / equal conditions / later sprouts'));$('seeds-check').onclick=()=>{const a=+$('float').value,b=+$('sink').value,n=+$('seed-sample').value;feedback(n>0&&[n,a,b].every(Number.isInteger)&&a>=0&&b>=0&&a+b===n?'Your counts match the original sample. Floating and sinking are observations, not a viability pass/fail test. Keep both groups and observe germination over the packet’s period.':'Check the sample count and both groups. Do not silently discard floating seeds or invent later sprouts.')}}
 else if(activity===2&&(step===1||step===2)){desk(field('crop','Crop / variety and seed source')+field('packet-depth','Packet / teacher-confirmed sowing depth')+field('packet-spacing','Packet / teacher-confirmed spacing')+field('positions','Planned sowing positions','number')+notes('sowing-check','Marked positions and chosen depth checked with teacher')+'<p>The book’s 3 × 3 inch grid and 0.5–1 cm depth are conditional examples, not defaults for every seed.</p>')}
 else if(activity===3&&step===0){desk('<h3>Inspect first, then choose care</h3><label>Observed moisture<select id="moisture"><option value="">Choose after the approved check</option><option value="damp">Damp</option><option value="dry">Dry</option><option value="wet">Very wet / puddling</option></select></label><button id="care">Read the workbook response</button>'+notes('care-record','Actual condition, teacher guidance, action and amount'));$('care').onclick=()=>feedback(({damp:'Damp: wait and recheck.',dry:'Dry: water slowly near the base until the root zone is moistened, following the teacher-approved check.',wet:'Very wet or puddling: stop and ask the teacher to check drainage.'})[$('moisture').value]||'Use the teacher-approved moisture check first. Tiny seedlings need shallower, gentler checks.')}
 else if(activity===3&&(step===1||step===2)){desk(notes('plant-evidence','Observed plant or leaf evidence — no automatic treatment')+notes('teacher-decision','Teacher’s actual decision / selected label instructions, or no treatment needed')+notes('care-product','Product, dilution, amount, reason and restrictions — only if supplied by the teacher')+'<p>The simulator supplies no feed, neem or homemade preparation recipe. “No treatment needed” remains a valid result, as in the book.</p>')}
 else if(activity===4&&step===1){tareDesk()}
 else if(activity===4&&step===3){desk(field('harvest-mass','Actual usable harvest · grams','number')+field('local-price','Dated comparable local price · ₹ / kg','number')+field('material-cost','Recorded material costs counted · ₹','number')+notes('price-source','Crop, price source/date and organic or conventional comparison')+'<button id="harvest-value">Calculate estimated value</button><div id="harvest-result" class="metrics"></div>');$('harvest-value').onclick=()=>{const ids=['harvest-mass','local-price','material-cost'];if(ids.some(id=>$(id).value===''||+$(id).value<0)){feedback('Use checked non-negative measurements and cost evidence first.');return}const r=CSLModel.harvest(+$('harvest-mass').value,+$('local-price').value,+$('material-cost').value);$('harvest-result').innerHTML='<div class="metric">Estimated market value<b>₹'+r.value.toFixed(2)+'</b></div><div class="metric">Value minus counted costs<b>₹'+r.difference.toFixed(2)+'</b></div>';feedback('Estimated market value is not cash received unless a sale happened. This simple material comparison excludes labour and overheads; it is not complete business profit.')}}
 else general();
}
function tareDesk(){desk('<h3>Tare / Zero weighing rehearsal</h3>'+field('bowl-mass','Measured empty bowl · g','number')+field('gross-mass','Bowl plus contents · g','number')+'<button id="tare">Tare the empty bowl</button> <button id="net">Read net mass</button><div id="scale" class="scale-display">— g</div><p class="fine">Enter actual scale readings. This browser does not invent a harvest or food mass.</p>');let tared=false;$('tare').onclick=()=>{if($('bowl-mass').value===''){feedback('Record the empty bowl’s measured mass first.');return}tared=true;$('scale').textContent='0 g · tared';feedback('Tare removes the empty container’s displayed mass. Add the contents on your actual scale and record the stable net reading.')};$('net').onclick=()=>{if(!tared||$('gross-mass').value===''){feedback('Record the empty bowl, tare it, and enter the measured bowl-plus-contents mass first.');return}const n=CSLModel.net(+$('gross-mass').value,+$('bowl-mass').value);if(n===null){feedback('Check your readings: gross mass cannot be less than the empty bowl in this calculation.');return}$('scale').textContent=n+' g · net';feedback('Calculated net mass: '+n+' g. Record units and only the precision your actual scale supports.')};}
function kioskDesk(){
 if(activity===0&&step===2){desk('<h3>Place the three zone labels</h3><div id="zones" class="task-cards"></div><button id="zone-cycle">Move the first zone to the end</button><p>Read the zones from receiving towards service. Keep used tools, waste and records/payment separate.</p><button id="zone-check">Check the route order</button>'+notes('counter-map','My actual counter map / clean and dirty routes / one change'));let zones=['SERVE','RECEIVE & WASH','PREPARE'];const draw=()=>{$('zones').innerHTML=zones.map(z=>'<div><strong>'+z+'</strong></div>').join('')};draw();$('zone-cycle').onclick=()=>{zones.push(zones.shift());draw()};$('zone-check').onclick=()=>feedback(zones.join('|')==='RECEIVE & WASH|PREPARE|SERVE'?'The three zone labels follow the workbook task order. A real partner still needs to test the counter route for crossings.':'Use RECEIVE & WASH → PREPARE → SERVE, with separate used-tool, waste and records/payment places. Test and revise your actual layout.')}
 else if(activity===0&&step===3){desk('<h3>Controlled pouring rehearsal</h3>'+field('practice-pour','Observed practice water in cup · mL','number')+'<button id="pour-check">Compare with the book’s task</button>'+notes('pour-improve','First observation / partner’s turn / change on repeat'));$('pour-check').onclick=()=>feedback($('practice-pour').value==='100'?'Your recorded amount matches the 100 mL practice-water task. Pour over a tray, swap roles and do not drink practice water.':'The book’s task is to pour 100 mL practice water over a tray. Recheck the jug marking and your observation; do not guess a result.')}
 else if(activity===1&&(step===2||step===3)){surveyDesk()}
 else if(activity===2&&(step===1||step===3)){recipeDesk()}
 else if(activity===2&&step===2){desk('<h3>Follow the approved recipe order</h3>'+blocks(CSLBook.recipeCard.blocks.slice(2))+notes('actual-batch','Actual measured amounts, additions and changes approved by the teacher')+'<button data-open-page="57" class="secondary">Enlarge original recipe card</button>')}
 else if(activity===3&&step===1){desk(notes('welcome','Welcoming sentence / clear ingredient explanation')+notes('visitor-choice','How I accepted “no” respectfully')+'<button id="allergy">Rehearse an uncertain ingredient or allergy question</button>');$('allergy').onclick=()=>feedback('Refer the question to the teacher; never guess. Stop service if an ingredient is uncertain. This browser does not decide whether food is safe for a person.')}
 else if(activity===3&&(step===3||step===4)){desk('<h3>Return, sort and reset</h3>'+notes('local-sort','Teacher-agreed local labels and destinations for clean sample items')+notes('unknown-item','An item whose destination I checked / unknown item reported')+checkbox('returns-wash','Wash hands after returns or waste and before serving.')+checkbox('clean-utensils','Reset with clean serving utensils; never return visitor leftovers to the shared batch.')+notes('service-improve','One observed change for the next service round'))}
 else if(activity===4&&(step===0||step===1)){kioskCost()}
 else general();
}
function surveyDesk(){desk('<h3>Practice preference tally · anonymous and optional</h3>'+field('survey-a','Teacher-checked option A')+field('survey-b','Teacher-checked option B')+'<p>For each practice response choose A, B, neither or skipped. No names, personal restrictions or fabricated opinions are stored.</p><div class="survey-buttons">'+['A','B','Neither','Skipped'].map(x=>'<button data-vote="'+x+'">'+x+'</button>').join('')+'</div><div id="votes" class="metrics"></div><button id="clear-votes" class="secondary">Reset practice tally</button>'+notes('survey-conclusion','Actual survey evidence, ties, neither/skipped and teacher-reviewed decision'));const counts={A:0,B:0,Neither:0,Skipped:0};let n=0;function draw(){$('votes').innerHTML=Object.entries(counts).map(([k,v])=>'<div class="metric">'+k+'<b>'+v+'</b></div>').join('')}draw();document.querySelectorAll('[data-vote]').forEach(b=>b.onclick=()=>{if(n===6){feedback('The workbook invites up to six classmates once each. This rehearsal has six marks; reset to try another tally.');return}counts[b.dataset.vote]++;n++;draw();feedback('Practice marks: '+n+'. Keep real responses in the original survey log. A small snapshot does not establish the whole school’s preference.')});$('clear-votes').onclick=()=>{Object.keys(counts).forEach(k=>counts[k]=0);n=0;draw()};}
function recipeDesk(){desk('<h3>Original recipe-card arithmetic</h3><p>Workbook example for three small trial portions: cooked, drained chickpeas 150 g; prepared cucumber 75 g; safe drinking water 300 mL; prepared lemon juice 15 mL. Use only if the teacher approves this recipe for the group.</p>'+field('recipe-portions','Planned equal trial portions','number','3')+'<button id="recipe-scale">Scale the workbook example</button><div id="recipe-result" class="metrics"></div>'+notes('recipe-actual','Actual measured and served amounts / teacher-approved adaptation')+'<button data-open-page="57" class="secondary">See original recipe card</button>');$('recipe-scale').onclick=()=>{const n=+$('recipe-portions').value;if(!Number.isInteger(n)||n<=0){feedback('Choose a positive whole number of trial portions for this arithmetic exercise.');return}const r=CSLModel.recipe(n);$('recipe-result').innerHTML=Object.entries(r).map(([k,v])=>'<div class="metric">'+k+'<b>'+v.toFixed(1)+(k==='water'||k==='lemon'?' mL':' g')+'</b></div>').join('');feedback('Scaled example only, not a completed food trial. Lemon juice adds to the drink batch: three source portions total 315 mL before actual handling losses, not 300 mL. Record actual served amounts; teacher clearance remains required.')};}
function kioskCost(){desk('<h3>One clearly defined batch of one item</h3>'+field('batch-cost','Counted batch cost · ₹','number')+field('usable-made','Usable portions actually made','number')+field('approved-price','Teacher-approved price per portion · ₹','number')+field('sold','Portions actually sold','number')+'<button id="cost-check">Calculate my cost and receipts</button><div id="cost-result" class="metrics"></div>'+notes('cost-evidence','Actual ingredient amounts, price evidence, supplies and costs included')+'<p>Keep reusable equipment purchases separate. A display does not require tasting or sales.</p>');$('cost-check').onclick=()=>{const ids=['batch-cost','usable-made','approved-price','sold'];if(ids.some(id=>$(id).value===''||+$(id).value<0)||+$('usable-made').value<=0||!Number.isInteger(+$('usable-made').value)||!Number.isInteger(+$('sold').value)||+$('sold').value>+$('usable-made').value){feedback('Use checked non-negative figures, at least one usable portion, and sales no greater than portions made. Record zero sales if none occurred.');return}const r=CSLModel.kiosk(+$('batch-cost').value,+$('usable-made').value,+$('approved-price').value,+$('sold').value);$('cost-result').innerHTML='<div class="metric">Counted cost / usable portion<b>₹'+r.unitCost.toFixed(2)+'</b></div><div class="metric">Receipts<b>₹'+r.receipts.toFixed(2)+'</b></div><div class="metric">Surplus / shortfall on counted costs<b>₹'+r.surplus.toFixed(2)+'</b></div>';feedback('A price is not a profit. Receipts use portions actually sold, not all portions made. The remaining figure covers only the costs included on your sheet; teacher supervises real money handling.')};}
$('reflection').oninput=()=>{state().reflection=$('reflection').value;persist()};
$('save').onclick=()=>{state().reflection=$('reflection').value;try{persist();const project='skillos.project.'+(form==='life'?'container-garden-6':'farm-table-6'),record=JSON.parse(localStorage.getItem(project)||'{}');record.simulator=record.simulator||{};record.simulator[String(activity)]={activity:activity<0?'Meet the Lab':current().title,observation:state().reflection,modelFeedback:lastEvidence,workbookFields:state().fields,basis:'Class 6 original workbook v34',kind:'workbook rehearsal / learner-entered record',savedAt:new Date().toISOString()};localStorage.setItem(project,JSON.stringify(record));$('save-status').textContent='Saved to this project’s workbook notebook in this browser.'}catch{$('save-status').textContent='Could not save. Copy your record before leaving; browser storage is unavailable.'}};
$('reset').onclick=()=>{stop();render()};window.addEventListener('pagehide',stop);step=state().step||0;render();
